const $=s=>document.querySelector(s),app=$('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={title:'Pip and the Flying Machine',author:'A little author',chapters:[{id:1,title:'A very big idea',text:'A dog wanted to fly. He built a plane. It did not work. A bird helped him. Then they flew together.',picture:'story.svg',expanded:null,previous:null}],current:1};
const defaultCharacters=[{id:'pip',name:'Pip',kind:'Curious little dog',description:'A small brown dog with floppy ears, a red scarf, and pilot goggles.',color:'#ebd4ad'},{id:'robin',name:'Robin',kind:'Helpful bird',description:'A small robin with a warm red chest, soft brown wings, and a clever smile.',color:'#ecd3c4'}];
function blankBook(){return {id:'unsaved',type:'chapter',title:'New book',author:'A little author',status:'working',chapters:[{id:1,title:'The beginning',text:'',picture:null,expanded:null,previous:null}],current:1}}
let library;try{library=JSON.parse(localStorage.getItem('kw-child-library-v2'))}catch{}if(!Array.isArray(library?.books)){let legacy;try{legacy=JSON.parse(localStorage.getItem('kw-child-book-v1'))}catch{}library={books:legacy?[{...legacy,id:'first-book',type:'chapter',status:'working',updated:Date.now()}]:[],characters:defaultCharacters,activeId:legacy?'first-book':null}}
library.books.forEach(b=>{b.type??='chapter'});library.characters??=defaultCharacters;let book=library.books.find(b=>b.id===library.activeId)||library.books[0]||blankBook();let mode='books',page=0,readVersion='draft',growth='short',reading=false,recognition=null,lastFocus=null,autosave,bookFilter='all',newBookType=null,grownProposal=null;
const c=()=>book.chapters.find(x=>x.id===book.current)||book.chapters[0];
const wordCount=t=>t.trim()?t.trim().split(/\s+/).length:0;
function save(){if(window.prototypeResetInProgress)return;try{if(library.books.includes(book))library.activeId=book.id;localStorage.setItem('kw-child-library-v2',JSON.stringify(library))}catch{toast('This device is full. Ask a grown-up to save a copy.')}}
function storyParts(x){let at=x.pictureOffset;if(at==null){const first=x.text.match(/^[\s\S]*?[.!?](?=\s|$)/);at=first?first[0].length:x.text.length}at=Math.max(0,Math.min(at,x.text.length));return {before:x.text.slice(0,at),after:x.text.slice(at).replace(/^\s*\n\s*/,'').trimStart()}}
function latestSentence(x){const ranges=[...x.text.matchAll(/[^.!?\n]+(?:[.!?]+["”’']*|$)/g)].map(m=>{const text=m[0].trim();return {text,start:m.index+m[0].indexOf(text),end:m.index+m[0].length}}).filter(r=>r.text);if(!ranges.length)return null;const cursor=x.lastEditOffset??x.text.length;return ranges.find(r=>cursor>r.start&&cursor<=r.end)||ranges[ranges.length-1]}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
const btn=(s,a,cls='')=>`<button class="btn ${cls}" data-action="${a}">${s}</button>`;
function side(){const x=c();$('#chapters').innerHTML=`<a class="back back-to-books" href="#books">← My Books</a><h2 class="book-name">${esc(book.title)}</h2><div class="author">By ${esc(book.author)}</div><div class="side-label">MY CHAPTERS</div><div class="chapter-list"><button class="chapter-item cover-item ${mode==='cover'?'active':''}" data-action="cover"><span class="number">▤</span><span><strong>My Cover</strong><small>Title, picture & author</small></span></button>${book.chapters.map((ch,i)=>`<button class="chapter-item ${mode==='write'&&ch.id===x.id?'active':''}" data-chapter="${ch.id}" ${mode==='write'&&ch.id===x.id?'aria-current="page"':''}><span class="number">${i+1}</span><span><strong>${esc(ch.title||'My chapter')}</strong><small>${wordCount(ch.text)} words</small></span></button>`).join('')}</div><button class="add-chapter" data-action="add-chapter">＋ New chapter</button><div class="side-bottom">${btn('↓ Save a copy','export','secondary')}<details class="tiny"><summary>For grown-ups</summary><p>Local prototype. Books stay in this browser. Writing coaching, story extensions, and picture changes use sample content. No live AI or image service is connected.</p></details></div>`;$('#mobile-book-name').textContent=book.title}
const workspaceTop=()=>`<div class="topline"><a class="back" href="#books">← My Books</a><span class="crumb">${mode==='read'?'READING MY BOOK':mode==='cover'?'MY COVER':(book.type==='picture'?'PAGE ':'CHAPTER ')+(book.chapters.indexOf(c())+1)}</span></div>`;
function chapterPictures(x){if(!Array.isArray(x.pictures))x.pictures=x.picture?[{id:'picture-'+x.id,src:x.picture,characterIds:x.pictureCharacterIds||[],note:x.pictureNote||''}]:[];return x.pictures}
function storyParagraphs(x){return x.text.split(/\n\s*\n/)}
function paragraphAtOffset(x,offset){return Math.max(0,Math.min(storyParagraphs(x).length-1,x.text.slice(0,offset??0).split(/\n\s*\n/).length-1))}
function inlineChapterText(x){const parts=storyParagraphs(x),pictures=chapterPictures(x);pictures.forEach(pic=>{pic.afterParagraph=Math.max(0,Math.min(parts.length-1,pic.afterParagraph??0))});let out=parts.map((text,i)=>`<div class="chapter-paragraph"><label for="${i===0?'story-text':'story-paragraph-'+i}" class="sr-only">Paragraph ${i+1}</label><textarea id="${i===0?'story-text':'story-paragraph-'+i}" class="story-text paragraph-text" data-story-part="${i}" data-part-count="1" placeholder="Write here…" rows="${Math.max(2,Math.ceil(text.length/65))}">${esc(text)}</textarea></div>${pictures.map((pic,j)=>pic.afterParagraph===i?`<figure class="inline-chapter-picture"><img src="${esc(pic.src)}" alt="Chapter picture ${j+1}"><button class="picture-edit-float" data-edit-chapter-picture="${j}" aria-label="Edit picture ${j+1}">✎ Edit picture</button></figure>`:'').join('')}`).join('');if(pictures.some(pic=>pic.afterParagraph===parts.length-1))out+=`<div class="chapter-paragraph"><label for="story-continuation" class="sr-only">Continue writing</label><textarea id="story-continuation" class="story-text paragraph-text" data-story-part="${parts.length}" data-part-count="0" placeholder="Continue writing…" rows="2"></textarea></div>`;return out}
function rememberParagraphCaret(el){const fields=[...document.querySelectorAll('[data-story-part]')],i=fields.indexOf(el);if(i<0)return;c().lastEditOffset=fields.slice(0,i).reduce((n,field)=>n+field.value.length+2,0)+el.selectionStart}
function picturesSection(x){const pictures=chapterPictures(x);return `<section class="chapter-pictures" aria-label="Chapter pictures"><div class="pictures-section-heading"><h2>Pictures <span>${pictures.length}</span></h2><button class="btn secondary" data-action="picture">＋ Add picture</button></div>${pictures.length?`<div class="chapter-pictures-grid">${pictures.map((p,i)=>`<figure class="chapter-picture-card"><img src="${esc(p.src)}" alt="Chapter picture ${i+1}"><button class="picture-edit-float" data-edit-chapter-picture="${i}" aria-label="Edit picture ${i+1}">✎ Edit</button><figcaption>Picture ${i+1}</figcaption></figure>`).join('')}</div>`:''}</section>`}
function editor(){if(book.type==='picture')return pictureBookEditor();const x=c();return `${workspaceTop()}<section class="editor-card focused-editor"><div class="editor-top"><span class="tag">CHAPTER ${book.chapters.indexOf(x)+1}</span><div class="chapter-tools"><button class="icon-btn" data-action="move-up" ${book.chapters.indexOf(x)===0?'disabled':''} aria-label="Move chapter earlier">↑</button><button class="icon-btn" data-action="move-down" ${book.chapters.indexOf(x)===book.chapters.length-1?'disabled':''} aria-label="Move chapter later">↓</button><button class="icon-btn" data-action="undo-writing" ${x.previous==null?'disabled':''} aria-label="Undo last writing change">↶ Undo</button></div></div><label for="chapter-title" class="sr-only">Chapter title</label><input id="chapter-title" class="chapter-title" value="${esc(x.title)}" placeholder="Chapter title" maxlength="120"><div class="chapter-writing-flow">${inlineChapterText(x)}</div><div class="editor-footer"><button class="voice-btn" data-action="voice"><span>🎙</span> Dictate</button><button class="voice-btn add-inline-picture" data-action="picture">＋ Add picture</button><span class="word-count" id="word-count">${wordCount(x.text)} words</span></div></section><div class="helpers writing-actions"><button class="helper" data-action="coach"><span class="symbol">✧</span><h3>Help my words</h3></button><button class="helper grow" data-action="grow"><span class="symbol">❋</span><h3>Grow my story</h3></button></div>`}
const dictionary={curious:'Wanting to find out or learn something new.',blueprint:'A drawing that shows how to build something.',glided:'Moved smoothly and gently through the air.',sturdy:'Strong and not easy to break.',determined:'Ready to keep trying, even when something is hard.',tinkered:'Made small changes to try to make something work.',meadow:'An open field with grass and flowers.',soared:'Flew high in the sky.',noticed:'Saw or became aware of something.',adventure:'An exciting experience or journey.'};
function highlight(t){return esc(t).replace(/\b(curious|blueprint|glided|sturdy|determined|tinkered|meadow|soared|noticed|adventure)\b/gi,w=>`<button class="new-word" data-word="${w.toLowerCase()}" aria-label="What does ${w} mean?">${w}</button>`)}
function paragraphs(){const x=c();return readVersion==='grown'&&x.expanded?x.expanded.paragraphs:x.text.split(/\n\s*\n/).filter(x=>x.trim())}
function readingCapacity(withImage){const mobile=innerWidth<=750,width=mobile?innerWidth-70:(Math.min(innerWidth-70,1050)*(withImage?.53:1))-65,stage=innerHeight-(mobile?210:190),image=mobile&&withImage?Math.min(150,innerHeight*.2):0,lines=Math.max(3,Math.floor((stage-image-100)/31)),wordsPerLine=Math.max(4,Math.floor(width/58));return Math.max(18,Math.min(withImage?100:180,lines*wordsPerLine))}
function readingLeaves(){const x=c(),paras=paragraphs(),pictures=chapterPictures(x),leaves=[];paras.forEach((text,index)=>{const images=pictures.filter(pic=>Math.min(paras.length-1,pic.afterParagraph??0)===index),words=text.trim().split(/\s+/);let first=true;while(words.length){const image=first?images[0]:null,limit=readingCapacity(!!image);leaves.push({texts:[words.splice(0,limit).join(' ')],image});first=false}images.slice(1).forEach(image=>leaves.push({texts:[],image}))});if(!leaves.length){pictures.forEach(image=>leaves.push({texts:[],image}));if(!leaves.length)leaves.push({texts:['No text yet.'],image:null})}const compact=[];for(const leaf of leaves){const prev=compact[compact.length-1];if(prev&&!leaf.image&&wordCount([...prev.texts,...leaf.texts].join(' '))<=readingCapacity(!!prev.image))prev.texts.push(...leaf.texts);else compact.push(leaf)}return compact}
function reader(){const x=c(),leaves=readingLeaves();page=Math.min(Math.max(page,0),leaves.length-1);const leaf=leaves[page],unit=book.type==='picture'?'Page':'Chapter',index=book.chapters.indexOf(x);return `<section class="screen-reader"><div class="reader-heading-bar"><a href="#books" class="back">← My Books</a><h1>${esc(book.title)}</h1></div><nav class="reader-chapter-chips" aria-label="${unit}s">${book.chapters.map((ch,i)=>`<button data-read-chapter="${ch.id}" aria-label="${unit} ${i+1}: ${esc(ch.title)}" ${ch.id===x.id?'aria-current="page"':''}>${unit} ${i+1}</button>`).join('')}</nav><div class="reader-version-bar"><div class="story-version-tabs" aria-label="Story version"><button data-action="read-draft" aria-pressed="${readVersion==='draft'}">Original story</button><button data-action="read-grown" aria-pressed="${readVersion==='grown'}">Bigger story ✧</button></div>${btn(reading?'■ Stop':'▷ Read aloud','read-aloud','secondary')}</div><article class="reader-page-stage ${leaf.image?'has-image':''}" aria-label="Reading page ${page+1}">${leaf.image?`<div class="reader-leaf-image"><img src="${esc(leaf.image.src)}" alt="Story illustration"></div>`:''}<div class="reader-leaf-text"><span class="tag">${unit.toUpperCase()} ${index+1}</span><h2>${esc(x.title)}</h2><div id="reading-text">${leaf.texts.map(t=>`<p>${highlight(t)}</p>`).join('')}</div></div></article><div class="reading-footer"><button class="btn secondary" data-action="prev-page" ${page===0&&index===0?'disabled':''}>← Previous</button><span aria-live="polite">${page+1} / ${leaves.length}</span><button class="btn secondary" data-action="next-page">${page===leaves.length-1?(index<book.chapters.length-1?'Next '+unit.toLowerCase()+' →':'Finish ✓'):'Next →'}</button></div></section>`}
function cover(){return `${workspaceTop()}<div class="cover-editor"><div class="welcome"><div><h1>Cover</h1></div></div><div class="cover-preview"><img id="cover-image" src="${esc(book.cover||'story.svg')}" alt="My cover picture"><h2 id="cover-title">${esc(book.title)}</h2><p id="cover-author">By ${esc(book.author)}</p></div><div class="field"><label for="book-title">My book is called</label><input class="input" id="book-title" value="${esc(book.title)}" maxlength="120"></div><div class="field"><label for="book-author">Written by</label><input class="input" id="book-author" value="${esc(book.author)}" maxlength="80"></div><div class="tools-row">${btn('▧ Pick a cover picture','cover-picture','secondary')}${btn('Done ✓','write')}</div></div>`}
function stopReading(){if('speechSynthesis'in window)window.speechSynthesis.cancel();reading=false}
function render(){stopReading();const exampleKey=location.hash==='#example-picture'?'picture':location.hash==='#example-chapter'?'chapter':null;if(exampleKey){if(book.id!==starterExamples[exampleKey].id)book=JSON.parse(JSON.stringify(starterExamples[exampleKey]))}else if(book.example&&!location.hash.startsWith('#finished-')){book=library.books.find(b=>b.id===library.activeId)||library.books[0]||blankBook()}mode=location.hash.startsWith('#finished-')?'end':exampleKey?'read':location.hash==='#read'?'read':location.hash==='#cover'?'cover':location.hash==='#write'?'write':location.hash==='#characters'?'characters':location.hash==='#start'?'start':'books';if(['write','cover','read'].includes(mode)&&!book.example&&!library.books.includes(book)){mode='books'}document.body.classList.toggle('completion-view',mode==='end');document.body.classList.toggle('library-view',['books','characters','start'].includes(mode));document.body.classList.toggle('reader-view',mode==='read');document.body.classList.toggle('picture-book-view',book.type==='picture');document.body.classList.toggle('first-use-view',mode==='start'||mode==='books'&&!library.books.length);$('#chapters').classList.remove('open');$('[data-action="toggle-chapters"]').setAttribute('aria-expanded','false');side();app.innerHTML=mode==='end'?readingEndScreen({title:book.title,author:book.author,audience:location.hash==='#finished-guest'?'guest':'author',backHref:book.example?'#example-'+book.type:'#read',authorHref:'#finished-author',guestHref:'#finished-guest'}):mode==='books'?booksHome():mode==='start'?booksHome(true):mode==='characters'?charactersHome():mode==='read'?reader():mode==='cover'?cover():editor();document.querySelectorAll('.studio-nav a').forEach(a=>{if(a.hash==='#'+mode||mode==='start'&&a.hash==='#books')a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});save();window.scrollTo(0,0);if(location.hash==='#new')openNewBook()}
function closeModal(){if(recognition){recognition.abort();recognition=null}$('#modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.focus()}
function modal(content){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-top"><span class="symbol">✧</span><button class="close" data-action="close-modal" aria-label="Close">×</button></div>${content}</section></div>`;document.body.style.overflow='hidden';$('.close').focus()}
function coach(){const x=c(),range=latestSentence(x);if(!range){toast('Add your first idea, then try a little help.');$('#story-text')?.focus();return}const original=range.text;let suggestion=original,reason='' ;const rules=[[/\bflew\b/i,'soared','“Soared” tells us they flew high and smoothly.'],[/\bwent\b/i,'hurried','“Hurried” helps us imagine how the character moved.'],[/\bbig\b/i,'enormous','“Enormous” means very big. It helps the reader picture the size.'],[/\bsaid\b/i,'called','“Called” gives your character’s voice a little more energy.'],[/\ba dog\b/i,'a curious dog','“Curious” means wanting to find things out.'],[/\ba plane\b/i,'a homemade airplane','“Homemade” tells us the character built it.']];for(const [re,word,why]of rules){if(re.test(original)){suggestion=original.replace(re,word);reason=why;break}}suggestion=suggestion.charAt(0).toUpperCase()+suggestion.slice(1);if(!/[.!?]$/.test(suggestion))suggestion+='.';modal(`<h2 id="modal-title">Edit sentence</h2><div class="comparison original"><small>Original</small><p>${esc(original)}</p></div><div class="comparison"><label for="coach-suggestion">Suggested</label><textarea class="transcript" id="coach-suggestion">${esc(suggestion)}</textarea></div>${suggestion!==original&&reason?`<p class="coach-reason">${esc(reason)}</p>`:''}<p class="fine-note">Sample suggestion</p><div class="modal-actions">${btn('Cancel','close-modal','secondary')}${btn('Replace','accept-coach')}</div>`);$('[data-action="accept-coach"]').onclick=()=>{const chosen=$('#coach-suggestion').value.trim();if(!chosen){toast('Add a few words, or keep your own.');return}x.previous=x.text;x.previousPictureOffset=x.pictureOffset;x.text=x.text.slice(0,range.start)+chosen+x.text.slice(range.start+original.length);x.lastEditOffset=range.start+chosen.length;save();closeModal();render();toast('Just that sentence changed. Undo brings it back.')}}
function grow(){if(!c().text.trim()){toast('Tell us your idea first. A few words is enough.');return}const editing=mode==='write';growth=c().expanded?.length||'short';modal(`<h2 id="modal-title">Grow ${editing?(book.type==='picture'?'page':'chapter'):'story'}</h2><div class="choice"><button data-length="short" aria-pressed="${growth==='short'}"><strong>❋</strong>A little more<br><small>${editing?'A few more details':'A short read'}</small></button><button data-length="long" aria-pressed="${growth==='long'}"><strong>❋ ❋</strong>A bigger adventure<br><small>${editing?'More story to work with':'A longer read'}</small></button></div><div class="comparison original"><small>IT STARTS WITH MY WORDS</small><p style="font-size:17px;max-height:135px;overflow:auto">${esc(c().text)}</p></div><p class="fine-note">Sample AI text</p><div class="modal-actions">${btn('Cancel','close-modal','secondary')}${btn(editing?'Preview changes':'Grow & read →','make-grown','yellow')}</div>`)}
function expand(){const x=c();const dog=/dog/i.test(x.text)&&/plane|fly|flew|flying/i.test(x.text);const short=dog?['Pip was a curious little dog with soft brown ears and a nose that was always looking for something new. Every morning, he watched the birds fly over the meadow. “I wish I could do that,” he thought.','One sunny day, Pip drew a blueprint for an airplane. He found some old wood, two wheels, and a bright red scarf. He carefully joined the pieces and made two wide, sturdy wings.','The first try did not work. His plane rolled, bumped, and stopped. Pip felt disappointed, but he was determined to try again.','A little bird named Robin noticed a loose wheel. Together, they fixed it and tried once more. The plane glided down the hill and lifted into the sky. Pip laughed as Robin flew beside him. His big idea had become an adventure.']: [x.text,'What could your character see, hear, or feel in this moment? Imagine one small detail that makes the scene feel real.','A complete adventure can have a wish, a tricky problem, and something the character tries. Read your words again. Which part would you like to tell us more about?'];const long=dog?['Pip was a curious little dog with soft brown ears and a nose that was always looking for something new. He lived beside a wide meadow, where the grass tickled his paws and the wind made the daisies dance.','Every morning, he watched the birds rise above the trees. “What would my home look like from up there?” he wondered. A big idea was beginning to grow. Pip wanted to build an airplane.','He found a pencil and drew a blueprint on a crumpled sheet of paper. The drawing showed two wide wings, a seat for one small dog, and wheels for a speedy start. It was a plan he could follow.','In the shed, Pip collected wood, little wheels, and a bright red scarf. He measured each wing twice. He tinkered with the pieces until the frame felt sturdy. Then he climbed into the seat and rolled toward the hill.','Bump, rattle, stop! The airplane leaned to one side. Pip’s ears drooped. He had worked so hard. For a moment, he wanted to give up. But then he took a breath. He was determined to find out what had gone wrong.','“May I have a look?” asked Robin, a small bird on the fence. She noticed a wheel that wobbled and a wing that pointed too low. Pip held the wood while Robin helped him check the pieces. Together, they made the plane steady.','They tried again. The wheels rolled faster. The wind rushed past Pip’s ears. Then the airplane lifted! It glided above the meadow, and the little houses below looked like toy blocks. Robin soared beside him.','Pip smiled all the way home. Building the airplane had taken patience, a few changes, and help from a friend. Already, he was wondering where their next adventure might take them.']:short;
const proposal={source:x.text,paragraphs:growth==='long'?long:short,length:growth,isSample:true};if(mode==='write'){grownProposal={...proposal,bookId:book.id,chapterId:x.id};modal(`<h2 id="modal-title">Review changes</h2><details class="comparison original grown-original"><summary>Original text</summary><p>${esc(proposal.source)}</p></details><label for="grown-story-suggestion">Suggested text</label><textarea id="grown-story-suggestion" class="transcript grown-story-suggestion">${esc(proposal.paragraphs.join('\n\n'))}</textarea><p class="fine-note">Sample text · Undo restores the original.</p><div class="modal-actions">${btn('Cancel','close-modal','secondary')}${btn('Replace','accept-grown','yellow')}</div>`);return}x.expanded=proposal;save();closeModal();readVersion='grown';page=0;app.innerHTML=reader();window.scrollTo(0,0)}
function applyGrown(){const x=c(),text=$('#grown-story-suggestion')?.value.trim();if(!text){toast('Add some words, or keep your own.');return}if(!grownProposal||grownProposal.bookId!==book.id||grownProposal.chapterId!==x.id||grownProposal.source!==x.text){toast('Your chapter changed. Close this and grow it again.');return}x.previous=x.text;x.previousPictureOffset=x.pictureOffset;x.text=text;const firstBreak=text.indexOf('\n\n');x.pictureOffset=firstBreak>=0?firstBreak:text.length;x.lastEditOffset=text.length;book.updated=Date.now();grownProposal=null;save();closeModal();render();toast('Chapter updated. Undo brings your words back.')}
function voice(){modal(`<h2 id="modal-title">Say your next idea.</h2><p>Talk, check the words, then add them to your chapter.</p><button class="btn secondary" data-action="start-voice">🎙 Start listening</button><p class="fine-note" id="voice-status" role="status">Your browser will ask before using the microphone. You can type below instead. Browser speech services may use a network connection.</p><label for="transcript">The words I said</label><textarea id="transcript" class="transcript" placeholder="Your words appear here. You can fix them before adding."></textarea><div class="modal-actions">${btn('Not now','close-modal','secondary')}${btn('Add my words +','insert-transcript')}</div>`)}
function startVoice(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){$('#voice-status').textContent='This browser can’t listen yet. You can type your words below or use the microphone on your keyboard.';return}if(recognition)recognition.abort();recognition=new SR();recognition.lang='en-US';recognition.interimResults=false;recognition.onstart=()=>{$('#voice-status').textContent='Listening… say one idea. It will stop when you finish.'};recognition.onresult=e=>{if($('#transcript'))$('#transcript').value+=($('#transcript').value?' ':'')+e.results[0][0].transcript};recognition.onerror=()=>{if($('#voice-status'))$('#voice-status').textContent='We couldn’t hear that. Try again, or type your idea below.'};recognition.onend=()=>{if($('#voice-status')?.textContent.startsWith('Listening'))$('#voice-status').textContent='All done listening. Check your words below.';recognition=null};try{recognition.start()}catch{$('#voice-status').textContent='Listening is unavailable. You can type below instead.'}}
function savePicture(src,forCover){const ids=imageDraft?.ids||[],note=$('#picture-change')?.value.trim()||'';if(forCover){book.cover=src;book.coverCharacterIds=[...ids];book.coverPictureNote=note}else{const x=c(),pictures=chapterPictures(x),index=imageDraft?.pictureIndex;const item={id:index!=null?pictures[index].id:'picture-'+Date.now(),src,characterIds:[...ids],note,afterParagraph:+($('#picture-position')?.value??imageDraft?.afterParagraph??0)};if(index!=null)pictures[index]=item;else pictures.push(item);x.picture=pictures[0]?.src||null;x.pictureCharacterIds=pictures[0]?.characterIds||[];x.pictureNote=pictures[0]?.note||''}save();closeModal();render();toast('Picture saved')}
function usePicture(src,forCover){savePicture(src,forCover)}
function exportBook(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(book,null,2)],{type:'application/json'}));a.download='my-kindlewood-book.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('A book copy is saved to your downloads.')}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.storyPart===undefined)return;e.stopImmediatePropagation();const x=c(),fields=[...document.querySelectorAll('[data-story-part]')],index=fields.indexOf(el),start=fields.slice(0,index).reduce((n,f)=>n+(+f.dataset.partCount),0),oldCount=+el.dataset.partCount,newCount=el.value?el.value.split(/\n\s*\n/).length:1,delta=newCount-oldCount;chapterPictures(x).forEach(pic=>{if((pic.afterParagraph??0)>=start+Math.max(oldCount,1)-1)pic.afterParagraph=Math.max(0,(pic.afterParagraph??0)+delta)});el.dataset.partCount=newCount;const activeFields=fields.filter((f,i)=>f.value.length||i<fields.length-1);x.text=activeFields.map(f=>f.value).join('\n\n');rememberParagraphCaret(el);$('#word-count').textContent=`${wordCount(x.text)} words`;el.style.height='auto';el.style.height=Math.max(70,el.scrollHeight)+'px';book.updated=Date.now();side();clearTimeout(autosave);autosave=setTimeout(save,250)},true);
for(const name of ['click','keyup','select'])document.addEventListener(name,e=>{if(e.target.dataset?.storyPart!==undefined)rememberParagraphCaret(e.target)});
document.addEventListener('input',e=>{if(e.target.id==='chapter-title'){c().title=e.target.value;side()}if(e.target.id==='story-text'){c().text=e.target.value;c().lastEditOffset=e.target.selectionStart;$('#word-count').textContent=`${wordCount(c().text)} words`;side()}if(e.target.id==='book-title'){book.title=e.target.value;$('#cover-title').textContent=book.title;side()}if(e.target.id==='book-author'){book.author=e.target.value;$('#cover-author').textContent='By '+book.author;side()}if(['chapter-title','story-text','book-title','book-author'].includes(e.target.id)){book.updated=Date.now();clearTimeout(autosave);autosave=setTimeout(save,350)}});
document.addEventListener('change',e=>{if(e.target.id==='picture-upload'){const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024){toast('That picture is a little big. Choose one under 2 MB.');return}if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Choose a PNG, JPG, or WebP picture.');return}const r=new FileReader();r.onload=()=>usePicture(r.result,e.target.dataset.cover==='true');r.readAsDataURL(file)}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const x=c();if(b.dataset.chapter){book.current=+b.dataset.chapter;page=0;save();if(location.hash==='#write')render();else location.hash='write';return}if(b.dataset.length){growth=b.dataset.length;document.querySelectorAll('[data-length]').forEach(el=>el.setAttribute('aria-pressed',el===b));return}if(b.dataset.word){modal(`<h2 id="modal-title">${esc(b.dataset.word)}</h2><p style="font-family:Georgia;font-size:23px;color:#56657b">${dictionary[b.dataset.word]}</p><div class="modal-actions">${btn('▷ Say this word','say-word','secondary')}${btn('Got it ✓','close-modal')}</div>`);$('[data-action="say-word"]').onclick=()=>speak(b.dataset.word);return}if(b.dataset.picture){usePicture(b.dataset.picture,b.dataset.cover==='true');return}switch(b.dataset.action){case'close-modal':closeModal();break;case'coach':coach();break;case'grow':grow();break;case'make-grown':expand();break;case'accept-grown':applyGrown();break;case'voice':voice();break;case'start-voice':startVoice();break;case'insert-transcript':{const text=$('#transcript').value.trim();if(!text){toast('Add a few words first.');return}x.previous=x.text;x.previousPictureOffset=x.pictureOffset;x.text+=(x.text.trim()?'\n\n':'')+text;x.lastEditOffset=x.text.length;save();closeModal();render();toast('Your words are in your chapter ✓');break}case'undo-writing':if(x.previous!==null){const current=x.text,currentOffset=x.pictureOffset;x.text=x.previous;x.previous=current;x.pictureOffset=x.previousPictureOffset;x.previousPictureOffset=currentOffset;x.lastEditOffset=x.text.length;save();render();toast('Your earlier words are back.')}break;case'picture':picture();break;case'cover-picture':picture(true);break;case'cover':location.hash='cover';break;case'write':location.hash='write';break;case'export':exportBook();break;case'toggle-chapters':$('#chapters').classList.toggle('open');b.setAttribute('aria-expanded',$('#chapters').classList.contains('open'));break;case'add-chapter':modal(`<h2 id="modal-title">New chapter</h2><label for="new-chapter-title">Chapter name</label><input class="input" id="new-chapter-title" placeholder="The next big adventure" maxlength="120"><div class="modal-actions">${btn('Not yet','close-modal','secondary')}${btn('Let’s write →','confirm-chapter')}</div>`);$('#new-chapter-title').focus();break;case'confirm-chapter':{const id=Date.now();book.chapters.push({id,title:$('#new-chapter-title').value.trim()||'My next adventure',text:'',picture:null,expanded:null,previous:null});book.current=id;save();closeModal();if(location.hash==='#write')render();else location.hash='write';$('#chapters').classList.remove('open');break}case'move-up':case'move-down':{const i=book.chapters.indexOf(x),j=i+(b.dataset.action==='move-up'?-1:1);if(j<0||j>=book.chapters.length)return;[book.chapters[i],book.chapters[j]]=[book.chapters[j],book.chapters[i]];save();render();toast('Chapter moved ✓');break}case'read-draft':readVersion='draft';page=0;stopReading();app.innerHTML=reader();break;case'read-grown':if(!x.text.trim()){toast('No text to expand yet.');return}page=0;stopReading();if(!x.expanded){growth='short';expand()}else{readVersion='grown';app.innerHTML=reader()}break;case'next-page':if(page>=readingLeaves().length-1){const next=book.chapters[book.chapters.indexOf(x)+1];if(next){book.current=next.id;if(!c().expanded)readVersion='draft';page=0;save()}else{location.hash=book.example?'finished-guest':'finished-author';return}}else page++;stopReading();app.innerHTML=reader();break;case'prev-page':if(page>0)page--;else{const previous=book.chapters[book.chapters.indexOf(x)-1];if(previous){book.current=previous.id;if(!c().expanded)readVersion='draft';page=readingLeaves().length-1;save()}}stopReading();app.innerHTML=reader();break;case'text-size':{const paras=document.querySelectorAll('#reading-text p');const large=b.dataset.large!=='true';paras.forEach(p=>p.style.fontSize=large?'28px':'');b.dataset.large=String(large);b.textContent=large?'Aa −':'Aa ＋';break}case'read-aloud':if(reading){stopReading();b.textContent='▷ Read aloud'}else{speak(readingLeaves()[page].texts.join('\n\n'),()=>{reading=false;if($('[data-action="read-aloud"]'))$('[data-action="read-aloud"]').textContent='▷ Read aloud'});reading='speechSynthesis'in window;if(reading)b.textContent='■ Stop'}break;case'book-settings':location.hash='books';break;case'settings-cover':closeModal();location.hash='cover';break}});
function speak(text,end){if(!('speechSynthesis'in window)){toast('This browser can’t read aloud yet. Try your device’s reading tools.');return}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.83;u.onend=end||null;u.onerror=()=>{reading=false;if($('[data-action="read-aloud"]'))$('[data-action="read-aloud"]').textContent='▷ Read aloud';toast('Read-aloud paused. You can try again.')};window.speechSynthesis.speak(u)}
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const focus=[...$('.modal').querySelectorAll('button,input,textarea,a')].filter(x=>!x.disabled),first=focus[0],last=focus[focus.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('hashchange',()=>{page=0;render()});window.addEventListener('beforeunload',()=>{save();stopReading()});
function booksHome(forceEmpty=false){if(forceEmpty||!library.books.length)return emptyBooksHome();const typed=library.books,list=typed.filter(b=>bookFilter==='all'||b.status===bookFilter);return `<div class="library-heading simple-library-heading"><div><h1>My Books</h1></div>${btn('＋ Add new book','new-book')}</div><div class="book-filters" aria-label="Book progress">${[['all','All'],['working','Still creating'],['finished','Finished']].map(([key,label])=>`<button data-book-filter="${key}" aria-pressed="${bookFilter===key}">${label} <span>${key==='all'?typed.length:typed.filter(b=>b.status===key).length}</span></button>`).join('')}</div><div class="my-books-grid">${list.map(b=>{const isPicture=b.type==='picture',image=b.cover||b.chapters.find(ch=>ch.picture)?.picture;return `<article class="library-book ${isPicture?'picture-library-book':''}"><div class="library-cover ${b.status==='finished'?'finished-cover':''}"><span class="book-status">${b.status==='finished'?'✓ Finished':'✎ Still creating'}</span><div class="shelf-book">${image||!isPicture?`<img src="${esc(image||'story.svg')}" alt="Cover of ${esc(b.title)}">`:'<div class="empty-picture-cover" aria-hidden="true">▧</div>'}<h2>${esc(b.title)}</h2><small>By ${esc(b.author)}</small></div></div><div class="library-book-info"><span class="book-kind-label">${isPicture?'PICTURE BOOK':'CHAPTER BOOK'}</span><h3>${esc(b.title)}</h3><p>${b.chapters.length} ${isPicture?(b.chapters.length===1?'page':'pages'):(b.chapters.length===1?'chapter':'chapters')} · ${b.chapters.reduce((n,ch)=>n+wordCount(ch.text),0)} words</p><div class="library-book-actions"><button class="btn" data-book-edit="${esc(b.id)}">${b.status==='finished'?'Edit book':'Keep writing'} ✎</button><button class="btn secondary" data-book-read="${esc(b.id)}">Read ▷</button></div><button class="book-finish" data-finish-book="${esc(b.id)}">${b.status==='finished'?'Move to still creating':'✓ Mark as finished'}</button></div></article>`}).join('')||'<p class="empty-filter-result">No books in this view.</p>'}</div><details class="library-note"><summary>About this prototype</summary><p>Books save in this browser. AI writing and picture changes use sample content.</p></details>`}
function charactersHome(){return `<div class="library-heading"><div><span class="library-eyebrow">MY CHARACTER COLLECTION</span><h1>Meet your story friends.</h1><p>Keep their names and looks ready for every new adventure.</p></div>${btn('＋ New character','new-character')}</div><div class="my-characters-grid">${library.characters.map(ch=>`<article class="managed-character"><div class="character-portrait" style="background:${esc(ch.color)}">${esc(ch.name.charAt(0))}<span>✧</span></div><div class="character-fields"><label>Name<input class="input" data-character-id="${esc(ch.id)}" data-property="name" value="${esc(ch.name)}" maxlength="60"></label><label>Who are they?<input class="input" data-character-id="${esc(ch.id)}" data-property="kind" value="${esc(ch.kind)}" maxlength="120"></label><label>What do they look like?<textarea class="input" data-character-id="${esc(ch.id)}" data-property="description" maxlength="1000">${esc(ch.description)}</textarea></label></div><span class="character-save-note">✓ Changes save as you type</span></article>`).join('')}</div><a href="#books" class="back characters-back">← Back to My Books</a>`}
let imageDraft=null;
function picture(forCover=false,pictureIndex=null){const item=forCover?{src:book.cover,characterIds:book.coverCharacterIds,note:book.coverPictureNote}:pictureIndex!=null?chapterPictures(c())[pictureIndex]:null;imageDraft={forCover,pictureIndex,src:item?.src||'story.svg',ids:[...(item?.characterIds||[])],note:item?.note||'',afterParagraph:item?.afterParagraph??paragraphAtOffset(c(),c().lastEditOffset)};modal(`<h2 id="modal-title">${forCover?'Cover picture':pictureIndex!=null?'Edit picture':'Add picture'}</h2><div class="picture-workspace">${!forCover&&book.type!=='picture'?`<label for="picture-position">Insert after</label><select id="picture-position" class="input">${storyParagraphs(c()).map((_,i)=>`<option value="${i}" ${i===imageDraft.afterParagraph?'selected':''}>Paragraph ${i+1}</option>`).join('')}</select>`:''}<img class="picture-big-preview" id="picture-big-preview" src="${esc(imageDraft.src)}" alt="Picture preview"><label>Characters</label><div class="picture-character-picks">${library.characters.map(ch=>`<label class="picture-character-pick"><input type="checkbox" data-image-character="${esc(ch.id)}" ${imageDraft.ids.includes(ch.id)?'checked':''}><span style="background:${esc(ch.color)}">${esc(ch.name.charAt(0))}</span><strong>${esc(ch.name)}</strong></label>`).join('')}</div><a class="manage-picture-characters" href="#characters" data-close-link>Manage characters ↗</a><label for="picture-change">Changes</label><textarea class="input" id="picture-change" placeholder="e.g. Add Robin. Make the sky pink.">${esc(imageDraft.note)}</textarea><label style="margin-top:18px">Style</label><div class="picture-options"><button class="picture-choice" data-image-option="story.svg" aria-pressed="${imageDraft.src==='story.svg'}"><img src="story.svg" alt="Sunny day">Day</button><button class="picture-choice" data-image-option="evening.svg" aria-pressed="${imageDraft.src==='evening.svg'}"><img src="evening.svg" alt="Sunset">Sunset</button></div><label for="picture-upload">Upload picture</label><input class="input" id="picture-upload" type="file" accept="image/png,image/jpeg,image/webp" data-cover="${forCover}"><p class="fine-note">Sample art · AI changes are simulated.</p><div class="modal-actions">${btn('Cancel','close-modal','secondary')}${btn('Save picture','apply-picture')}</div></div>`)}
function selectBook(id,read=false){save();const selected=library.books.find(b=>String(b.id)===id);if(!selected)return;book=selected;if(library.books.includes(book))library.activeId=book.id;page=0;readVersion='draft';if(read)book.current=book.chapters[0].id;save();const dest=read?'#read':'#write';if(location.hash===dest)render();else location.hash=dest}
document.addEventListener('input',e=>{if(e.target.dataset.characterId){const ch=library.characters.find(ch=>ch.id===e.target.dataset.characterId);if(ch){ch[e.target.dataset.property]=e.target.value;save()}}});
document.addEventListener('change',e=>{if(e.target.id==='read-chapter'){book.current=+e.target.value;if(!c().expanded)readVersion='draft';page=0;stopReading();save();app.innerHTML=reader()}if(e.target.dataset.imageCharacter&&imageDraft){const id=e.target.dataset.imageCharacter;if(e.target.checked)imageDraft.ids.push(id);else imageDraft.ids=imageDraft.ids.filter(x=>x!==id)}});
document.addEventListener('click',e=>{if(e.target.closest('[data-close-link]')){closeModal();return}const b=e.target.closest('button');if(!b)return;if(b.dataset.newBookType){newBookType=b.dataset.newBookType;document.querySelectorAll('[data-new-book-type]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('[data-action="create-book"]').disabled=false;return}if(b.dataset.exampleBook){readVersion='draft';page=0;location.hash='example-'+b.dataset.exampleBook;return}if(b.dataset.picturePage){book.current=+b.dataset.picturePage;page=0;readVersion='draft';save();render();return}if(b.dataset.picturePageStep){const next=book.chapters[book.chapters.indexOf(c())+(+b.dataset.picturePageStep)];if(next){book.current=next.id;page=0;readVersion='draft';save();render()}return}if(b.dataset.readChapter){book.current=+b.dataset.readChapter;page=0;stopReading();if(readVersion==='grown'&&!c().expanded&&c().text.trim()){growth='short';expand()}else{if(!c().text.trim())readVersion='draft';save();app.innerHTML=reader()}return}if(b.dataset.editChapterPicture!==undefined){picture(false,+b.dataset.editChapterPicture);return}if(b.dataset.bookEdit){selectBook(b.dataset.bookEdit);return}if(b.dataset.bookRead){selectBook(b.dataset.bookRead,true);return}if(b.dataset.bookFilter){bookFilter=b.dataset.bookFilter;app.innerHTML=booksHome();return}if(b.dataset.finishBook){const b1=library.books.find(x=>String(x.id)===b.dataset.finishBook);b1.status=b1.status==='finished'?'working':'finished';save();app.innerHTML=booksHome();return}if(b.dataset.imageOption&&imageDraft){imageDraft.src=b.dataset.imageOption;$('#picture-big-preview').src=imageDraft.src;document.querySelectorAll('[data-image-option]').forEach(x=>x.setAttribute('aria-pressed',x===b));return}switch(b.dataset.action){case'add-picture-page':{const next={id:Date.now(),title:'Page '+(book.chapters.length+1),text:'',picture:null,pictures:[],expanded:null,previous:null};book.chapters.push(next);book.current=next.id;page=0;save();render();break}case'new-book':openNewBook();break;case'create-book':{if(!newBookType){toast('Choose a book type.');return}const id='book-'+Date.now();const ch={id:Date.now(),title:newBookType==='picture'?'Page 1':'The beginning',text:'',picture:null,expanded:null,previous:null};book={id,type:newBookType,title:$('#new-book-title').value.trim()||'My new adventure',author:'A little author',status:'working',chapters:[ch],current:ch.id,updated:Date.now()};library.books.unshift(book);save();closeModal();location.hash='write';break}case'new-character':modal(`<h2 id="modal-title">New character</h2><label for="new-character-name">Their name</label><input class="input" id="new-character-name" placeholder="e.g. Luna" maxlength="60"><label for="new-character-kind" style="margin-top:18px">Who are they?</label><input class="input" id="new-character-kind" placeholder="A moon-loving rabbit" maxlength="120"><div class="modal-actions">${btn('Not yet','close-modal','secondary')}${btn('Add my character +','create-character')}</div>`);$('#new-character-name').focus();break;case'create-character':{const name=$('#new-character-name').value.trim();if(!name){toast('Give your new friend a name.');return}library.characters.push({id:'character-'+Date.now(),name,kind:$('#new-character-kind').value.trim(),description:'',color:'#dcd9ee'});save();closeModal();app.innerHTML=charactersHome();toast('Your new friend is ready.');break}case'apply-picture':if(imageDraft)savePicture(imageDraft.src,imageDraft.forCover);break}});
function openNewBook(){newBookType=null;modal(`<h2 id="modal-title">New book</h2><div class="new-book-types" aria-label="Choose a book type"><button data-new-book-type="picture" aria-pressed="false"><span aria-hidden="true">▧</span><strong>Picture book</strong><small>A picture and words on every page</small></button><button data-new-book-type="chapter" aria-pressed="false"><span aria-hidden="true">▤</span><strong>Chapter book</strong><small>A longer story, chapter by chapter</small></button></div><label for="new-book-title">Title</label><input class="input" id="new-book-title" placeholder="Book title" maxlength="120"><div class="modal-actions">${btn('Cancel','close-modal','secondary')}<button class="btn" data-action="create-book" disabled>Create book →</button></div>`)}
function picturePageTabs(){return `<nav class="picture-page-tabs" aria-label="Book pages">${book.chapters.map((p,i)=>`<button data-picture-page="${p.id}" ${p.id===c().id?'aria-current="page"':''}>Page ${i+1}</button>`).join('')}${mode==='write'?'<button class="add-page-tab" data-action="add-picture-page">＋ Add page</button>':''}</nav>`}
function picturePageControls(){const index=book.chapters.indexOf(c());return `<div class="picture-page-controls"><button class="btn secondary" data-picture-page-step="-1" ${index===0?'disabled':''}>← Previous</button><span>Page ${index+1} of ${book.chapters.length}</span><button class="btn secondary" data-picture-page-step="1" ${index===book.chapters.length-1?'disabled':''}>Next →</button></div>`}
function pictureBookEditor(){const x=c(),image=chapterPictures(x)[0];return `<div class="picture-book-toolbar"><a class="back" href="#books">← My Books</a><span class="picture-book-name">${esc(book.title)}</span><button class="btn secondary" data-action="cover">Edit cover</button></div>${picturePageTabs()}<section class="picture-page-editor"><div class="picture-page-image">${image?`<img src="${esc(image.src)}" alt="Picture for page ${book.chapters.indexOf(x)+1}"><button class="picture-edit-float" data-edit-chapter-picture="0">✎ Edit picture</button>`:'<div class="picture-page-placeholder"><span aria-hidden="true">▧</span><button class="btn secondary" data-action="picture">＋ Add picture</button></div>'}</div><div class="picture-page-writing"><div class="editor-top"><span class="tag">PAGE ${book.chapters.indexOf(x)+1}</span><button class="icon-btn" data-action="undo-writing" ${x.previous==null?'disabled':''}>↶ Undo</button></div><label for="chapter-title" class="sr-only">Page title</label><input id="chapter-title" class="chapter-title" value="${esc(x.title)}" placeholder="Page title" maxlength="120"><label for="story-text" class="sr-only">Page text</label><textarea id="story-text" class="story-text picture-page-text" placeholder="Write here…">${esc(x.text)}</textarea><div class="editor-footer"><button class="voice-btn" data-action="voice">🎙 Dictate</button><span class="word-count" id="word-count">${wordCount(x.text)} words</span></div></div></section><div class="helpers writing-actions"><button class="helper" data-action="coach"><span class="symbol">✧</span><h3>Help my words</h3></button><button class="helper grow" data-action="grow"><span class="symbol">❋</span><h3>Grow my story</h3></button></div>${picturePageControls()}`}
function pictureBookReader(){const x=c(),images=chapterPictures(x);return `${workspaceTop()}<div class="reading-layout picture-book-reader"><h1 class="reading-book-title">${esc(book.title)}</h1>${picturePageTabs()}<div class="reader-version-bar"><div class="story-version-tabs" aria-label="Story version"><button data-action="read-draft" aria-pressed="${readVersion==='draft'}">Original story</button><button data-action="read-grown" aria-pressed="${readVersion==='grown'}">Bigger story ✧</button></div>${btn(reading?'■ Stop':'▷ Read aloud','read-aloud','secondary')}</div><article class="read-book">${images.length?images.map((img,i)=>`<img src="${esc(img.src)}" alt="Page picture ${i+1}">`).join(''):'<div class="reader-picture-placeholder" aria-hidden="true">▧</div>'}<div class="read-page"><span class="tag">PAGE ${book.chapters.indexOf(x)+1}</span><h2>${esc(x.title)}</h2><div id="reading-text">${paragraphs().map(p=>`<p>${highlight(p)}</p>`).join('')||'<p>No text yet.</p>'}</div></div></article>${picturePageControls()}${readVersion==='grown'?'<p class="reading-source">Sample AI expansion</p>':''}</div>`}
const starterExamples={
picture:{id:'example-picture',example:true,type:'picture',title:'Pip’s First Flight',author:'KindleWood · Example',status:'finished',current:101,chapters:[{id:101,title:'A big idea',text:'Pip looked up at the sky. “I want to fly,” he said.',picture:'story.svg',pictures:[{id:'example-pic-1',src:'story.svg',characterIds:['pip'],note:''}],expanded:null,previous:null},{id:102,title:'A helping hand',text:'Robin helped Pip build two strong wings. They tried, fixed, and tried again.',picture:'story.svg',pictures:[{id:'example-pic-2',src:'story.svg',characterIds:['pip','robin'],note:''}],expanded:null,previous:null},{id:103,title:'Up they go',text:'The little plane lifted into the sunset. “We did it!” cheered Pip.',picture:'evening.svg',pictures:[{id:'example-pic-3',src:'evening.svg',characterIds:['pip','robin'],note:''}],expanded:null,previous:null}]},
chapter:{id:'example-chapter',example:true,type:'chapter',title:'The Flying Machine',author:'KindleWood · Example',status:'finished',current:201,chapters:[{id:201,title:'The plan',text:'Pip watched the birds glide over the meadow. He wondered what the world looked like from above.\n\nIn his shed, he found wood, two little wheels, and a red scarf. He drew a plan for a flying machine. It would take patience, but Pip was ready to begin.',picture:'story.svg',pictures:[{id:'example-ch-1',src:'story.svg',characterIds:['pip'],note:''}],expanded:null,previous:null},{id:202,title:'One more try',text:'The first flight ended with a bump. Pip’s ears drooped. Then Robin landed on the fence. “Let’s look together,” she said.\n\nThey noticed a loose wheel and a tilted wing. After a few careful changes, the plane rolled smoothly. Pip tried again—and this time, it soared.',picture:'evening.svg',pictures:[{id:'example-ch-2',src:'evening.svg',characterIds:['pip','robin'],note:''}],expanded:null,previous:null}]}
};
function emptyBooksHome(){return `<div class="library-heading empty-library-heading"><h1>My Books</h1></div><section class="first-book-action" aria-label="Create your first book"><div class="first-book-icon" aria-hidden="true">▤<span>＋</span></div>${btn('＋ Add new book','new-book')}</section><section class="book-examples" aria-labelledby="example-heading"><h2 id="example-heading">Examples</h2><div class="example-books-grid">${[['picture',starterExamples.picture],['chapter',starterExamples.chapter]].map(([key,b])=>`<button class="example-book-card ${key==='picture'?'picture-example-card':''}" data-example-book="${key}"><div class="example-mini-cover"><img src="${key==='picture'?'story.svg':'evening.svg'}" alt=""><span>${key==='picture'?'▧':'▤'}</span></div><div><small>${key==='picture'?'PICTURE BOOK':'CHAPTER BOOK'}</small><h3>${esc(b.title)}</h3><span class="example-view-label">View example →</span></div></button>`).join('')}</div></section>`}
window.addEventListener('resize',()=>{if(mode==='read'){stopReading();app.innerHTML=reader()}});
document.addEventListener('keydown',e=>{if(mode!=='read'||$('.modal')||document.querySelector('dialog[open]')||e.altKey||e.metaKey||e.ctrlKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;const action=e.key==='ArrowRight'?'next-page':e.key==='ArrowLeft'?'prev-page':null;if(action){const button=$(`[data-action="${action}"]`);if(button&&!button.disabled){e.preventDefault();button.click()}}});
render();
